package com.mendes.scheduling_platform.security; public final class TenantContext { private static final ThreadLocal<Long> VALUE=new ThreadLocal<>(); private TenantContext(){} public static void set(Long id){VALUE.set(id);} public static Long getRequired(){ Long id=VALUE.get(); if(id==null) throw new IllegalStateException("Tenant ausente no contexto"); return id;} public static Long get(){return VALUE.get();} public static void clear(){VALUE.remove();} }
